package local.z6panel;

import android.app.*;
import android.graphics.*;
import android.graphics.drawable.*;
import android.os.*;
import android.util.LruCache;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;

/** Paged gallery with explicit selection, organization and reversible draft movement. */
final class WallpaperLibrary {
 interface Host {void open(String id);void options(String id);void receive();void importFiles();void back();void selectionSaved();void importErrors();}
 private final Activity activity;private final WallpaperStore store;private final Host host;private final Handler ui=new Handler(Looper.getMainLooper());
 private final ThreadPoolExecutor worker=new ThreadPoolExecutor(1,1,10,TimeUnit.SECONDS,new ArrayBlockingQueue<>(10),r->new Thread(()->{android.os.Process.setThreadPriority(android.os.Process.THREAD_PRIORITY_BACKGROUND);r.run();},"Z6-thumbnails"));
 private final LruCache<String,Bitmap> cache=new LruCache<String,Bitmap>(4*1024*1024){protected int sizeOf(String k,Bitmap v){return v.getAllocationByteCount();}protected void entryRemoved(boolean e,String k,Bitmap old,Bitmap next){if(old!=next&&!old.isRecycled())old.recycle();}};
 private final Set<String> selected=new LinkedHashSet<>();private final List<ImageView> images=new ArrayList<>();private final Map<String,LinearLayout> cards=new LinkedHashMap<>();private final Map<String,TextView> labels=new HashMap<>();private final List<LinearLayout> rows=new ArrayList<>();
 private List<WallpaperStore.Photo> photos=Collections.emptyList();private ArrayList<String> draft;private int offset,epoch;private boolean visible,busy,selecting,selectPresentation,ordering,participantsOnly,orderDirect,moving,focusPage;private String focus="",pendingMessage="";private LinearLayout root,grid,tools;private int errorCount;private Button errorsButton;private Button saveButton;private AlertDialog confirmation;TextView status;
 WallpaperLibrary(Activity a,WallpaperStore s,Host h){activity=a;store=s;host=h;worker.allowCoreThreadTimeOut(true);}
 private int dp(int v){return Math.round(v*activity.getResources().getDisplayMetrics().density);}
 private TextView text(String s,int size){TextView t=new TextView(activity);t.setText(s);t.setTextSize(size);t.setTextColor(0xFFBBC3CC);return t;}
 private GradientDrawable background(boolean focused,boolean checked){GradientDrawable d=new GradientDrawable();d.setColor(checked?0xFF2A4143:0xFF222E38);d.setCornerRadius(dp(5));if(focused)d.setStroke(dp(2),0xFFD2DFE5);return d;}
 private Button button(LinearLayout row,String label,Runnable action){Button b=new Button(activity);b.setText(label);b.setAllCaps(false);b.setTextSize(13);b.setTextColor(Color.WHITE);b.setPadding(dp(5),0,dp(5),0);StateListDrawable state=new StateListDrawable();state.addState(new int[]{android.R.attr.state_focused},background(true,false));state.addState(new int[]{},background(false,false));b.setBackground(state);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(39),1);p.setMargins(dp(3),0,dp(3),0);row.addView(b,p);b.setOnClickListener(v->{if(busy){status.setText("Espera a que termine la operación");return;}action.run();});return b;}
 void choose(){selectPresentation=false;selecting=false;ordering=false;participantsOnly=false;moving=false;draft=null;selected.clear();show();}
 void focusPhoto(String id){focus=id;focusPage=true;}
 void importErrors(int count){errorCount=count;if(errorsButton!=null){errorsButton.setText("Errores ("+count+")");errorsButton.setVisibility(count>0?View.VISIBLE:View.GONE);}}
 void message(String value){pendingMessage=value;if(status!=null&&visible)status.setText(value);}
 void save(Bundle b){b.putInt("library.offset",offset);b.putString("library.focus",focus);b.putBoolean("library.selecting",selecting);b.putBoolean("library.presentation",selectPresentation);b.putBoolean("library.ordering",ordering);b.putBoolean("library.participants",participantsOnly);b.putBoolean("library.direct",orderDirect);b.putBoolean("library.moving",moving);b.putStringArrayList("library.selected",new ArrayList<>(selected));if(draft!=null)b.putStringArrayList("library.draft",draft);}
 void restore(Bundle b){offset=b.getInt("library.offset",offset);focus=b.getString("library.focus",focus);selecting=b.getBoolean("library.selecting",selecting);selectPresentation=b.getBoolean("library.presentation",selectPresentation);ordering=b.getBoolean("library.ordering",ordering);participantsOnly=b.getBoolean("library.participants",participantsOnly);orderDirect=b.getBoolean("library.direct",orderDirect);moving=b.getBoolean("library.moving",moving);ArrayList<String> ids=b.getStringArrayList("library.selected");if(ids!=null){selected.clear();selected.addAll(ids);}draft=b.getStringArrayList("library.draft");}
 void selectPresentation(){selectPresentation=true;selecting=true;ordering=false;participantsOnly=false;moving=false;draft=null;selected.clear();android.content.SharedPreferences p=activity.getSharedPreferences("panel",0);for(WallpaperStore.Photo photo:WallpaperSelection.eligible(p,store.photos()))selected.add(photo.id);offset=0;show();}
 void order(boolean participants,boolean direct){selectPresentation=false;selecting=false;ordering=true;participantsOnly=participants;orderDirect=direct;moving=false;draft=null;offset=0;show();}
 private void organize(){if(photos.isEmpty())return;new AlertDialog.Builder(activity).setTitle("Organizar mis fotos").setItems(new String[]{"Ordenar fotos","Seleccionar y eliminar","Eliminar todas"},(d,w)->{if(w==0)order(false,false);else if(w==1){selecting=true;selectPresentation=false;ordering=false;selected.clear();show();}else confirm(allIds());}).setNegativeButton("Volver",null).show();}
 private ArrayList<String> allIds(){ArrayList<String> ids=new ArrayList<>();for(WallpaperStore.Photo p:photos)ids.add(p.id);return ids;}
 void show(){hide();visible=true;final int token=epoch;root=new LinearLayout(activity);root.setOrientation(1);root.setPadding(dp(24),dp(12),dp(24),dp(12));root.setBackgroundColor(0xFF121722);TextView heading=text(selectPresentation?"Fotos de la presentación":ordering?"Ordenar fotos":"Mis fotos",22);heading.setTextColor(Color.WHITE);root.addView(heading);status=text("Cargando fotos…",12);root.addView(status,new LinearLayout.LayoutParams(-1,dp(25)));tools=new LinearLayout(activity);root.addView(tools);saveButton=null;
  if(selectPresentation){button(tools,"Usar todas",()->{WallpaperSelection.save(activity,true,selected);host.selectionSaved();});saveButton=button(tools,"Usar elegidas (0)",()->{if(selected.isEmpty())return;WallpaperSelection.save(activity,false,selected);host.selectionSaved();});button(tools,"Cancelar",host::back);}
  else if(ordering){button(tools,moving?"Guardar movimiento":"OK elige una foto para mover",()->{if(moving)saveOrder();else beginMove(focus);});button(tools,"Cancelar / volver",this::back);}
  else if(selecting){button(tools,"Seleccionar todas",()->{selected.addAll(allIds());refreshSelection();});saveButton=button(tools,"Eliminar (0)",()->confirm(new ArrayList<>(selected)));button(tools,"Cancelar selección",()->{selecting=false;selected.clear();show();});}
  else{button(tools,"Desde el celular",host::receive);button(tools,"Desde TV o USB",host::importFiles);button(tools,"Opciones de la foto",()->{if(!focus.isEmpty())host.options(focus);});button(tools,"Organizar",this::organize);errorsButton=button(tools,"Errores ("+errorCount+")",host::importErrors);errorsButton.setVisibility(errorCount>0?View.VISIBLE:View.GONE);}
  grid=new LinearLayout(activity);grid.setOrientation(1);LinearLayout.LayoutParams g=new LinearLayout.LayoutParams(-1,0,1);g.topMargin=dp(7);g.bottomMargin=dp(7);root.addView(grid,g);LinearLayout footer=new LinearLayout(activity);root.addView(footer);button(footer,"Anteriores",()->page(-1));TextView pages=text("",12);pages.setGravity(Gravity.CENTER);footer.addView(pages,new LinearLayout.LayoutParams(0,dp(39),1));button(footer,"Siguientes",()->page(1));button(footer,"Volver",this::back);activity.setContentView(root);
  worker.execute(()->{try{List<WallpaperStore.Photo> loaded=store.photos();if(participantsOnly)loaded=WallpaperSelection.eligible(activity.getSharedPreferences("panel",0),loaded);if(draft!=null){Map<String,WallpaperStore.Photo> map=new HashMap<>();for(WallpaperStore.Photo p:loaded)map.put(p.id,p);List<WallpaperStore.Photo> arranged=new ArrayList<>();for(String id:draft)if(map.containsKey(id))arranged.add(map.remove(id));for(WallpaperStore.Photo p:loaded)if(map.containsKey(p.id))arranged.add(p);loaded=arranged;}final List<WallpaperStore.Photo> result=loaded;ui.post(()->{if(!visible||token!=epoch)return;photos=result;if(focusPage){int index=allIds().indexOf(focus);if(index>=0)offset=index/8*8;focusPage=false;}Set<String> ids=new HashSet<>(allIds());selected.retainAll(ids);offset=Math.min(offset,Math.max(0,((photos.size()-1)/8)*8));pages.setText((offset/8+1)+" / "+Math.max(1,(photos.size()+7)/8));updateHint();draw(token);});}catch(Exception e){ui.post(()->{if(visible&&token==epoch)status.setText(e.getMessage());});}});
 }
 private void page(int direction){if(moving)return;int next=offset+direction*8;if(next<0||next>=photos.size())return;offset=next;focus="";show();}
 private void updateHint(){if(!pendingMessage.isEmpty()){status.setText(pendingMessage);pendingMessage="";return;}status.setText(moving?"← → ↑ ↓ Mover · OK guardar · Atrás cancelar":ordering?"Elige una foto y pulsa OK para moverla":selectPresentation?"Marca fotos y pulsa Usar elegidas. Todas incluye fotos futuras.":selecting?"Marca las copias que quieres eliminar":"OK usar foto · Mantén OK para opciones · "+photos.size()+" / 50 fotos");}
 private void draw(int token){for(ImageView image:images)image.setImageDrawable(null);images.clear();grid.removeAllViews();cards.clear();labels.clear();rows.clear();if(photos.isEmpty()){TextView empty=text("No hay fotos disponibles. Recibe o importa una imagen.",16);empty.setGravity(Gravity.CENTER);grid.addView(empty,new LinearLayout.LayoutParams(-1,-1));refreshSelection();return;}for(int row=0;row<2;row++){LinearLayout line=new LinearLayout(activity);grid.addView(line,new LinearLayout.LayoutParams(-1,0,1));rows.add(line);for(int col=0;col<4;col++){int index=offset+row*4+col;if(index>=photos.size()){line.addView(new View(activity),new LinearLayout.LayoutParams(0,-1,1));continue;}WallpaperStore.Photo photo=photos.get(index);LinearLayout card=new LinearLayout(activity);card.setOrientation(1);card.setPadding(dp(5),dp(5),dp(5),dp(5));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-1,1);p.setMargins(dp(3),dp(3),dp(3),dp(3));line.addView(card,p);cards.put(photo.id,card);card.setFocusable(true);card.setClickable(true);card.setContentDescription(photo.name+" · "+photo.dimensions());card.setBackground(background(false,selected.contains(photo.id)));ImageView thumb=new ImageView(activity);thumb.setBackgroundColor(WallpaperImages.DARK);thumb.setScaleType(photo.fit.equals("contain")?ImageView.ScaleType.FIT_CENTER:ImageView.ScaleType.CENTER_CROP);card.addView(thumb,new LinearLayout.LayoutParams(-1,0,1));images.add(thumb);TextView label=text(photo.name,12);label.setSingleLine(true);label.setEllipsize(android.text.TextUtils.TruncateAt.END);labels.put(photo.id,label);card.addView(label);card.addView(text(photo.dimensions()+" · "+WallpaperImages.bytes(photo.file.length()),10));card.setOnFocusChangeListener((v,f)->{if(f)focus=photo.id;card.setBackground(background(f,selected.contains(photo.id)));});card.setOnClickListener(v->{if(busy)return;focus=photo.id;if(ordering){if(moving)saveOrder();else beginMove(photo.id);}else if(selecting){if(!selected.add(photo.id))selected.remove(photo.id);refreshSelection();}else host.open(photo.id);});card.setOnLongClickListener(v->{if(!busy&&!selecting&&!ordering){focus=photo.id;host.options(photo.id);return true;}return false;});card.setOnKeyListener((v,key,e)->{if(!moving||e.getAction()!=KeyEvent.ACTION_DOWN)return false;int delta=key==21?-1:key==22?1:key==19?-4:key==20?4:0;if(delta==0)return false;moveDraft(delta);return true;});Bitmap found=cache.get(photo.id);if(found!=null)thumb.setImageBitmap(found);else loadThumbnail(photo,thumb,token);}}
  refreshSelection();LinearLayout target=cards.get(focus);if(target==null&&!cards.isEmpty())target=cards.values().iterator().next();if(target!=null)target.requestFocus();}
 private void loadThumbnail(WallpaperStore.Photo p,ImageView view,int token){try{worker.execute(()->{if(!visible||token!=epoch)return;Bitmap bitmap=null;try{bitmap=store.thumbnail(p);}catch(Exception ignored){}final Bitmap ready=bitmap;ui.post(()->{if(ready==null)return;if(!visible||token!=epoch){ready.recycle();return;}cache.put(p.id,ready);view.setImageBitmap(ready);});});}catch(RejectedExecutionException ignored){}}
 private void refreshSelection(){if(saveButton!=null){saveButton.setText((selectPresentation?"Usar elegidas (":"Eliminar (")+selected.size()+")");saveButton.setEnabled(!busy&&!selected.isEmpty());saveButton.setAlpha(saveButton.isEnabled()?1:.45f);}for(Map.Entry<String,LinearLayout> e:cards.entrySet()){boolean checked=selected.contains(e.getKey());e.getValue().setBackground(background(e.getValue().hasFocus(),checked));for(WallpaperStore.Photo p:photos)if(p.id.equals(e.getKey())){labels.get(p.id).setText((moving&&focus.equals(p.id)?"↔ ":checked?"✓ ":"")+p.name);break;}}}
 private void beginMove(String id){if(id==null||id.isEmpty()||!allIds().contains(id))return;focus=id;draft=allIds();moving=true;updateHint();refreshSelection();}
 private void moveDraft(int delta){if(!moving||draft==null)return;int from=draft.indexOf(focus),to=from+delta;if(from<0||to<0||to>=draft.size())return;Collections.swap(draft,from,to);Map<String,WallpaperStore.Photo> map=new HashMap<>();for(WallpaperStore.Photo p:photos)map.put(p.id,p);List<WallpaperStore.Photo> arranged=new ArrayList<>();for(String id:draft)arranged.add(map.get(id));photos=arranged;int nextOffset=(to/8)*8;if(nextOffset!=offset){offset=nextOffset;draw(epoch);return;}Map<String,LinearLayout> retained=new LinkedHashMap<>(cards);for(LinearLayout row:rows)row.removeAllViews();for(int i=0;i<8;i++){int index=offset+i;LinearLayout row=rows.get(i/4);if(index<photos.size()){LinearLayout card=retained.get(photos.get(index).id);if(card==null){draw(epoch);return;}LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-1,1);p.setMargins(dp(3),dp(3),dp(3),dp(3));row.addView(card,p);}else row.addView(new View(activity),new LinearLayout.LayoutParams(0,-1,1));}refreshSelection();LinearLayout focused=cards.get(focus);if(focused!=null)focused.requestFocus();}
 private void saveOrder(){if(!moving||draft==null)return;final ArrayList<String> order=new ArrayList<>(draft);busy=true;worker.execute(()->{String error="";try{store.reorder(order);}catch(Exception e){error=e.getMessage();}final String result=error;ui.post(()->{busy=false;moving=false;draft=null;if(visible){show();final int token=epoch;ui.postDelayed(()->{if(visible&&token==epoch)status.setText(result.isEmpty()?"Orden guardado":result);},250);}});});}
 private void confirm(List<String> ids){if(ids.isEmpty())return;confirmation=new AlertDialog.Builder(activity).setTitle("¿Eliminar "+ids.size()+(ids.size()==1?" foto?":" fotos?")).setMessage("Se borrarán las fotos y miniaturas de Z6, sin papelera, para liberar espacio. Los originales externos se conservan.").setPositiveButton("Eliminar",(d,w)->remove(ids)).setNegativeButton("Cancelar",null).create();confirmation.show();}
 private void remove(List<String> ids){busy=true;refreshSelection();status.setText("Eliminando…");worker.execute(()->{String result;String old=activity.getSharedPreferences("panel",0).getString("wallpaper_mode","original");try{result=store.removeMany(ids).message();if(old.equals("slideshow")&&activity.getSharedPreferences("panel",0).getString("wallpaper_mode","original").equals("original"))result+=" · Presentación detenida: no quedan fotos elegidas";}catch(Exception e){result=e.getMessage();}final String message=result;ui.post(()->{busy=false;selected.clear();selecting=false;if(visible){show();final int token=epoch;ui.postDelayed(()->{if(visible&&token==epoch)status.setText(message);},300);}});});}
 void back(){if(busy){status.setText("Espera a que termine la operación");return;}if(moving){moving=false;draft=null;show();return;}if(ordering&&!orderDirect||selecting&&!selectPresentation){choose();return;}host.back();}
 void hide(){visible=false;epoch++;if(!busy)worker.getQueue().clear();ui.removeCallbacksAndMessages(null);if(confirmation!=null&&confirmation.isShowing())confirmation.dismiss();for(ImageView image:images)image.setImageDrawable(null);images.clear();cards.clear();labels.clear();rows.clear();cache.evictAll();}
 boolean busy(){return busy;}boolean moving(){return moving;}
 void trim(){epoch++;if(!busy)worker.getQueue().clear();for(ImageView image:images)image.setImageDrawable(null);cache.evictAll();}
 void destroy(){hide();worker.shutdownNow();}
 JSONObject inspect()throws JSONException{JSONArray ids=new JSONArray();for(String id:cards.keySet())ids.put(id);return new JSONObject().put("page",offset/8+1).put("visibleIds",ids).put("selectionCount",selected.size()).put("selecting",selecting).put("selectionPurpose",selectPresentation?"slideshow":selecting?"delete":"none").put("ordering",ordering).put("moving",moving).put("order",new JSONArray(allIds())).put("focusId",focus).put("thumbnailBytes",cache.size()).put("dialog",confirmation!=null&&confirmation.isShowing()).put("busy",busy);}
 String action(String action){if(!visible)return "NOT_VISIBLE";if(action.equals("organize"))organize();else if(action.equals("select_toggle")){selecting=!selecting;selectPresentation=false;selected.clear();show();}else if(action.startsWith("mark:")){String id=action.substring(5);if(store.find(id)==null)return "INVALID";selecting=true;if(!selected.add(id))selected.remove(id);refreshSelection();}else if(action.equals("save_selection")){if(!selectPresentation||selected.isEmpty())return "INVALID";WallpaperSelection.save(activity,false,selected);host.selectionSaved();}else if(action.equals("use_all")){WallpaperSelection.save(activity,true,selected);host.selectionSaved();}else if(action.equals("delete_selected"))confirm(new ArrayList<>(selected));else if(action.equals("delete_all"))confirm(allIds());else if(action.equals("confirm_delete")||action.equals("cancel_delete")){if(confirmation==null||!confirmation.isShowing())return "NO_DIALOG";confirmation.getButton(action.equals("confirm_delete")?AlertDialog.BUTTON_POSITIVE:AlertDialog.BUTTON_NEGATIVE).performClick();}else if(action.equals("next_page"))page(1);else if(action.equals("previous_page"))page(-1);else if(action.equals("order"))order(false,false);else if(action.startsWith("move_id:"))beginMove(action.substring(8));else if(action.startsWith("move_delta:"))moveDraft(Integer.parseInt(action.substring(11)));else if(action.equals("save_order"))saveOrder();else if(action.equals("cancel_order")){moving=false;draft=null;show();}else return "NOT_FOUND";return "OK";}
}
